_CORE_SRC = '# Action format: "[(from_node, to_node, count), ...]"\n# Payout: "revenue_p = sum of node_value[i] over all nodes i that player p owns"\n# Cost: "upkeep_p = UPKEEP * (UNITS_PER_PLAYER - units of p on its own base)"\n# Ownership, not capacity-sharing, determines revenue: capture requires a strict\n# majority at two consecutive turn ends. Bases cannot be owned.\nimport time\nfrom collections import defaultdict\n\nTIME_BUDGET = 0.25\nN_TURNS = 80\nUPKEEP = 2.0\n\n\ndef payout(values, owned, units_at_home):\n    """The specification\'s exact per-turn profit function."""\n    return float(sum(v for v, owner in zip(values, owned) if owner)\n                 - UPKEEP * (20 - units_at_home))\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    lengths = {}\n    distance = [[10**6] * n for _ in range(n)]\n    for u in range(n):\n        distance[u][u] = 0\n    for u, v, length in edges:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n        lengths[u, v] = lengths[v, u] = int(length)\n        distance[u][v] = distance[v][u] = int(length)\n    for row in adjacency:\n        row.sort()\n    for k in range(n):\n        for i in range(n):\n            for j in range(n):\n                candidate = distance[i][k] + distance[k][j]\n                if candidate < distance[i][j]:\n                    distance[i][j] = candidate\n    hop = [[-1] * n for _ in range(n)]\n    for u in range(n):\n        for v in range(n):\n            if u != v:\n                for w in adjacency[u]:\n                    if lengths[u, w] + distance[w][v] == distance[u][v]:\n                        hop[u][v] = w\n                        break\n    return adjacency, lengths, distance, hop\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.memory = {}\n        self.bad_reports = 0\n\n    def _tokens(self, obs):\n        """Recover sticky destinations by matching actual, observable locations."""\n        tokens = []\n        turn = int(obs["turn"])\n        for node, count in enumerate(obs["player_units"]):\n            key = (node, turn)\n            previous = self.memory.get(key, [])\n            for k in range(count):\n                target = previous[k] if k < len(previous) else -1\n                tokens.append((node, 0, target))\n        for _, node, count, arrival in obs.get("player_transits", []):\n            previous = self.memory.get((node, arrival), [])\n            for k in range(count):\n                target = previous[k] if k < len(previous) else -1\n                tokens.append((node, arrival - turn, target))\n        return tokens\n\n    def _plan(self, obs, tokens, deadline):\n        """\n        Capture has a threshold, so its marginal return is not concave.\n        Allocate minimum majority bundles rather than incorrectly assigning\n        zero value to the first unit of a multi-unit capture.\n        """\n        _, _, distance, _ = self.map_data\n        n = obs["n_nodes"]\n        home = obs["player_base"]\n        enemy_home = obs["opponent_base"]\n        remaining = N_TURNS - obs["turn"]\n        values = obs["node_value"]\n        owned = obs["player_owned"]\n        enemy_owned = obs["opponent_owned"]\n        opponents = list(obs["opponent_units"])\n        for _, node, count, arrival in obs.get("opponent_transits", []):\n            if arrival <= obs["turn"] + 3:\n                opponents[node] += count\n\n        jobs = []\n        for node in range(n):\n            if node in (home, enemy_home) or values[node] <= 0:\n                continue\n            enemy = opponents[node]\n            if owned[node]:\n                # Ties defend existing ownership. Only pay for a garrison when\n                # actual deployed opponents can threaten it soon.\n                threat = enemy\n                for other in range(n):\n                    if other != enemy_home and distance[other][node] <= 2:\n                        threat = max(threat, opponents[other])\n                if threat <= 0:\n                    continue\n                required = max(1, enemy, min(threat, 2))\n                holding = True\n            else:\n                required = enemy + 1\n                holding = enemy > 0\n            if required <= len(tokens):\n                jobs.append((node, required, holding))\n\n        free = set(range(len(tokens)))\n        assignments = [home] * len(tokens)\n        while jobs and free and time.perf_counter() < deadline:\n            best = None\n            for node, required, holding in jobs:\n                if required > len(free):\n                    continue\n                choices = sorted(\n                    free,\n                    key=lambda i: (\n                        tokens[i][1] + distance[tokens[i][0]][node]\n                        - (1.75 if tokens[i][2] == node else 0.0),\n                        i,\n                    ),\n                )[:required]\n                arrivals = [\n                    tokens[i][1] + distance[tokens[i][0]][node]\n                    for i in choices\n                ]\n                delay = max(arrivals, default=0)\n                # A unit already at the node can finish a first lead now.\n                if not owned[node]:\n                    if delay == 0 and obs["player_lead_turns"][node] >= 1:\n                        capture_delay = 0\n                    else:\n                        capture_delay = max(1, delay)\n                else:\n                    capture_delay = max(0, delay - 1)\n                earning_turns = max(0, remaining - capture_delay)\n                if earning_turns <= 0:\n                    continue\n\n                multiplier = 2.0 if owned[node] or enemy_owned[node] else 1.0\n                reward = multiplier * values[node] * earning_turns\n                if holding:\n                    # Charge for the entire expected garrison commitment.\n                    cost = UPKEEP * (\n                        sum(arrivals) + required * earning_turns\n                    )\n                else:\n                    # Capture, then recall: include both travel legs and the\n                    # extra majority turn, clipping recall at the game end.\n                    cost = 0.0\n                    for i, arrival in zip(choices, arrivals):\n                        away = min(\n                            remaining,\n                            arrival + max(1, delay - arrival + 1)\n                            + max(0, distance[node][home] - 1),\n                        )\n                        cost += UPKEEP * away\n                sticky = sum(tokens[i][2] == node for i in choices)\n                net = reward - cost + 3.0 * sticky\n                # Prefer quick, cheap captures without losing total economics.\n                priority = net / (1.0 + 0.18 * delay + 0.35 * (required - 1))\n                candidate = (priority, net, -node, choices, node)\n                if best is None or candidate[:3] > best[:3]:\n                    best = candidate\n            if best is None or best[0] <= 1.0 or best[1] <= 1.0:\n                break\n            node = best[4]\n            for i in best[3]:\n                assignments[i] = node\n                free.remove(i)\n            jobs = [job for job in jobs if job[0] != node]\n        return assignments\n\n    def _legal_action(self, obs, tokens, targets):\n        """Aggregate, then replay each move against start-of-turn availability."""\n        _, lengths, _, hop = self.map_data\n        turn = int(obs["turn"])\n        requested = defaultdict(int)\n        memory = defaultdict(list)\n        for (node, wait, _), target in zip(tokens, targets):\n            if wait:\n                memory[node, turn + wait].append(int(target))\n                continue\n            destination = hop[node][target] if target != node else -1\n            if destination >= 0:\n                requested[node, destination] += 1\n                arrival = turn + lengths[node, destination]\n                memory[destination, arrival].append(int(target))\n            else:\n                memory[node, turn + 1].append(int(target))\n\n        available = list(obs["player_units"])\n        action = []\n        for (source, destination), count in sorted(requested.items()):\n            if (source, destination) not in lengths:\n                continue\n            count = min(int(count), int(available[source]))\n            if count > 0:\n                action.append((int(source), int(destination), int(count)))\n                available[source] -= count\n        self.memory = dict(memory)\n        return action\n\n    def act(self, obs):\n        started = time.perf_counter()\n        deadline = started + max(0.0001, 0.55 * TIME_BUDGET)\n        if self.map_data is None:\n            self.map_data = preprocess_map(obs["n_nodes"], obs["edges"])\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0)):\n            self.bad_reports += 1\n        tokens = self._tokens(obs)\n        if not tokens:\n            return []\n        if self.bad_reports >= 2:\n            # Conservative recovery still earns from existing ownership while\n            # removing upkeep; never repeat a possibly inconsistent deployment.\n            targets = [int(obs["player_base"])] * len(tokens)\n        else:\n            targets = self._plan(obs, tokens, deadline)\n        return self._legal_action(obs, tokens, targets)\n'
